def reverse_string(s):
    '''Return the characters of s in reverse order.'''
    if not isinstance(s, str):
        raise TypeError('reverse_string expects a string')
    return s[::-1]


def reverse_words(text):
    '''Reverse each whitespace-separated word, keeping the word order.'''
    separator = ' '
    words = text.split(separator)
    return separator.join(reverse_string(word) for word in words)


def reverse_lines(text):
    newline = '\n'
    return newline.join(reverse_string(line) for line in text.splitlines())


def is_palindrome(s, ignore_case=True):
    cleaned = ''.join(ch for ch in s if ch.isalnum())
    if ignore_case:
        cleaned = cleaned.lower()
    return cleaned == reverse_string(cleaned)


def describe(s):
    if is_palindrome(s):
        label = 'palindrome'
    else:
        label = 'not a palindrome'
    template = '{0!r} -> {1!r} ({2})'
    return template.format(s, reverse_string(s), label)


def parse_arguments(argv):
    mode = 'chars'
    values = []
    for arg in argv:
        if arg == '-w':
            mode = 'words'
        elif arg == '-l':
            mode = 'lines'
        elif arg == '-c':
            mode = 'chars'
        elif arg.startswith('-'):
            raise ValueError('unknown option: ' + arg)
        else:
            values.append(arg)
    return mode, values


def transform(mode, value):
    if mode == 'words':
        return reverse_words(value)
    if mode == 'lines':
        return reverse_lines(value)
    return reverse_string(value)


def default_samples():
    return [
        'hello',
        'Python',
        'A man, a plan, a canal: Panama',
    ]


def main(argv=None):
    if argv is None:
        argv = default_samples()
    mode, values = parse_arguments(argv)
    if not values:
        print('nothing to reverse')
        return 1
    for value in values:
        if mode == 'chars':
            print(describe(value))
        else:
            print(transform(mode, value))
    return 0


if __name__ == '__main__':
    import sys

    sys.exit(main(sys.argv[1:] or None))

