import sys

DEFAULT_SAMPLES = [
    'Racecar',
    'Hello World',
    'A man, a plan, a canal: Panama',
    '12 21',
]


def normalize(text):
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    return ''.join(char.lower() for char in text if char.isalnum())


def is_palindrome(text):
    cleaned = normalize(text)
    return cleaned == cleaned[::-1]


def longest_palindromic_span(text):
    cleaned = normalize(text)
    best = ''
    for start in range(len(cleaned)):
        for end in range(start + len(best) + 1, len(cleaned) + 1):
            chunk = cleaned[start:end]
            if chunk == chunk[::-1]:
                best = chunk
    return best


def verdict_of(text):
    if is_palindrome(text):
        return 'palindrome'
    return 'not a palindrome'


def describe(text):
    span = longest_palindromic_span(text)
    if span:
        detail = 'longest palindromic run: ' + span
    else:
        detail = 'no alphanumeric content'
    return '{0!r} is {1} ({2})'.format(text, verdict_of(text), detail)


def read_lines(argv):
    if argv:
        return argv
    if sys.stdin.isatty():
        return list(DEFAULT_SAMPLES)
    return [line.rstrip('\n') for line in sys.stdin if line.strip()]


def main(argv):
    lines = read_lines(argv)
    palindromes = 0
    for line in lines:
        print(describe(line))
        if is_palindrome(line):
            palindromes += 1
    summary = '{0} of {1} inputs were palindromes'.format(palindromes, len(lines))
    print('-' * len(summary))
    print(summary)
    return 0 if palindromes else 1


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))

