def sum_list(numbers):
    'Calculates the sum of numbers in a list.'
    total = 0
    if not isinstance(numbers, list):
        raise TypeError('Input must be a list.')
    for number in numbers:
        if not isinstance(number, (int, float)):
            raise TypeError('List elements must be numbers.')
        total += number
    return total

if __name__ == '__main__':
    test_cases = [
        ([1, 2, 3, 4], 10),
        ([], 0),
        ([10], 10),
        ([-1, 1], 0),
        ([1.5, 2.5], 4.0)
    ]
    for nums, expected in test_cases:
        result = sum_list(nums)
        assert result == expected, f'For {nums}, expected {expected} but got {result}.'
    print('All test cases passed successfully!')

    try:
        sum_list('not a list')
    except TypeError as e:
        print(f'Caught expected error: {e}')

    try:
        sum_list([1, 'a', 3])
    except TypeError as e:
        print(f'Caught another expected error: {e}')

