def simple_calculator(num1, operator, num2):
    if operator == '+':
        return num1 + num2
    elif operator == '-':
        return num1 - num2
    elif operator == '*':
        return num1 * num2
    elif operator == '/':
        if num2 == 0:
            return 'Error'
        return num1 / num2
    else:
        return 'Invalid operator'

if __name__ == '__main__':
    print(simple_calculator(10, '+', 5))
    print(simple_calculator(20, '-', 7))
    print(simple_calculator(4, '*', 6))
    print(simple_calculator(100, '/', 10))
    print(simple_calculator(10, '/', 0))
    print(simple_calculator(5, '^', 2))
    print('Test complete.')
    assert simple_calculator(1, '+', 1) == 2, 'Addition failed'
    assert simple_calculator(10, '/', 2) == 5.0, 'Division failed'

