def calculate_age(birth_year, current_year):
    'Calculates the age based on birth year and current year.'
    if not isinstance(birth_year, int) or not isinstance(current_year, int):
        raise TypeError('Both birth_year and current_year must be integers.')
    if current_year < birth_year:
        raise ValueError('Current year cannot be before birth year.')
    age = current_year - birth_year
    return age

if __name__ == '__main__':
    # Test cases for the function
    print(f'Test 1: calculate_age(1990, 2023) -> {calculate_age(1990, 2023)}')
    print(f'Test 2: calculate_age(2000, 2000) -> {calculate_age(2000, 2000)}')
    print(f'Test 3: calculate_age(1985, 2024) -> {calculate_age(1985, 2024)}')
    print(f'Test 4: calculate_age(2023, 2023) -> {calculate_age(2023, 2023)}')

    try:
        calculate_age(2025, 2024)
    except ValueError as e:
        print(f'Expected error for calculate_age(2025, 2024): {e}')

    try:
        calculate_age('1990', 2023)
    except TypeError as e:
        print(f'Expected error for calculate_age(\'1990\', 2023): {e}')

