def validate_email(email):
    'Validates a basic email format.'
    if '@' not in email:
        return False  # 'Missing @ symbol'

    parts = email.split('@')
    if len(parts) != 2:
        return False  # 'Too many @ symbols'

    local_part, domain_part = parts
    if not local_part or not domain_part:
        return False  # 'Empty local or domain part'

    if '.' not in domain_part:
        return False  # 'Missing dot in domain'

    at_index = email.find('@')
    dot_index = email.rfind('.')

    if at_index == -1 or dot_index == -1:
        return False  # 'Indices not found'

    if at_index > dot_index:
        return False  # '@ after .'

    if not all(c.isalnum() or c in '._-' for c in local_part):
        return False  # 'Invalid characters in local part'

    if not all(c.isalnum() or c in '.-' for c in domain_part):
        return False  # 'Invalid characters in domain part'

    return True # 'Email looks good'

