MONTH_NAMES = (
    'January',
    'February',
    'March',
    'April',
    'May',
    'June',
    'July',
    'August',
    'September',
    'October',
    'November',
    'December',
)

FIELD_NAMES = (
    'year',
    'month',
    'day',
)


def is_leap_year(year):
    if year % 400 == 0:
        return True
    if year % 100 == 0:
        return False
    return year % 4 == 0


def days_in_month(year, month):
    if month == 2:
        return 29 if is_leap_year(year) else 28
    if month in (4, 6, 9, 11):
        return 30
    return 31


def validate_date(year, month, day):
    for name, value in zip(FIELD_NAMES, (year, month, day)):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError(f'{name} must be an integer, got {type(value).__name__}')
    if not 1 <= month <= 12:
        raise ValueError(f'month out of range: {month}')
    limit = days_in_month(year, month)
    if not 1 <= day <= limit:
        raise ValueError(f'day out of range for month {month}: {day}')


def format_date(year, month, day):
    validate_date(year, month, day)
    return f'{year:04d}-{month:02d}-{day:02d}'


def parse_date(text):
    parts = text.strip().split('-')
    if len(parts) != 3:
        raise ValueError(f'expected YYYY-MM-DD, got {text!r}')
    year, month, day = (int(part) for part in parts)
    validate_date(year, month, day)
    return year, month, day


def long_form(year, month, day):
    validate_date(year, month, day)
    return f'{MONTH_NAMES[month - 1]} {day}, {year}'


def describe(year, month, day):
    stamp = format_date(year, month, day)
    if is_leap_year(year):
        note = 'leap year'
    else:
        note = 'common year'
    return f'{stamp} ({long_form(year, month, day)}, {note})'


def main():
    samples = [(2023, 7, 15), (2020, 1, 1), (1999, 12, 31), (2024, 2, 29)]
    for year, month, day in samples:
        print(describe(year, month, day))
    source = '2020-01-01'
    print(f'round trip: {format_date(*parse_date(source))}')
    try:
        format_date(2023, 2, 30)
    except ValueError as error:
        print(f'rejected: {error}')


if __name__ == '__main__':
    main()

