import sys


def reverse_words(sentence):
    if not isinstance(sentence, str):
        raise TypeError('sentence must be a string')
    words = sentence.split()
    words.reverse()
    return ' '.join(words)


def word_count(sentence):
    return len(sentence.split())


def is_palindromic_order(sentence):
    words = sentence.split()
    return words == words[::-1]


def describe(sentence):
    count = word_count(sentence)
    if count == 0:
        subject = 'no words'
    elif count == 1:
        subject = '1 word'
    else:
        subject = '{} words'.format(count)
    reversed_text = reverse_words(sentence)
    parts = [
        'input: ' + repr(sentence),
        'output: ' + repr(reversed_text),
        'contains ' + subject,
    ]
    if is_palindromic_order(sentence) and count > 1:
        parts.append('word order is symmetric')
    return '; '.join(parts)


def read_sentences(argv):
    if len(argv) > 1:
        return argv[1:]
    text = sys.stdin.read()
    return [line for line in text.splitlines() if line.strip()]


def main(argv=None):
    if argv is None:
        argv = sys.argv
    sentences = read_sentences(argv)
    if not sentences:
        sys.stderr.write('nothing to reverse\n')
        return 1
    for sentence in sentences:
        try:
            report = describe(sentence)
        except TypeError as error:
            sys.stderr.write('skipped: {}\n'.format(error))
            continue
        print(report)
    return 0


if __name__ == '__main__':
    sys.exit(main())

