def char_frequency(text):
    if not isinstance(text, str):
        raise TypeError('char_frequency expects a string')
    frequency_map = {}
    for character in text.lower():
        frequency_map[character] = frequency_map.get(character, 0) + 1
    return frequency_map


def letters_only(text):
    cleaned = ''.join(character for character in text if character.isalpha())
    return char_frequency(cleaned)


def most_common(frequency_map, limit=3):
    if limit < 1:
        raise ValueError('limit must be at least 1')
    ordered = sorted(frequency_map.items(), key=lambda pair: (-pair[1], pair[0]))
    return ordered[:limit]


def describe_character(character):
    if character == ' ':
        return '<space>'
    if character == '\t':
        return '<tab>'
    if character == '\n':
        return '<newline>'
    return character


def format_row(character, count, total):
