ABSOLUTE_ZERO_F = -459.67

DEGREE_SIGN = '\u00b0'

FAHRENHEIT_NAME = 'Fahrenheit'

CELSIUS_NAME = 'Celsius'


def fahrenheit_to_celsius(fahrenheit):
    return (float(fahrenheit) - 32.0) * 5.0 / 9.0


def parse_temperature(text):
    cleaned = text.strip().replace(DEGREE_SIGN, '')
    if cleaned.upper().endswith('F'):
        cleaned = cleaned[:-1].strip()
    if not cleaned:
        raise ValueError('no temperature value given')
    try:
        return float(cleaned)
    except ValueError:
        raise ValueError('cannot read {0!r} as a Fahrenheit value'.format(cleaned))


def validate_fahrenheit(fahrenheit):
    if fahrenheit < ABSOLUTE_ZERO_F:
        raise ValueError('{0:.2f} is below absolute zero'.format(fahrenheit))
    return fahrenheit


def describe(fahrenheit):
    celsius = fahrenheit_to_celsius(fahrenheit)
    if celsius <= 0.0:
        phase = 'water freezes'
    elif celsius >= 100.0:
        phase = 'water boils'
    else:
        phase = 'water stays liquid'
    return celsius, phase


def format_row(fahrenheit):
    celsius, phase = describe(validate_fahrenheit(fahrenheit))
    template = '{0} {1:.1f}'
    label = template.format(FAHRENHEIT_NAME, fahrenheit)
    value = '{0} {1:.2f}'.format(CELSIUS_NAME, celsius)
    return '{0:<20} -> {1:<18} ({2})'.format(label, value, phase)


def convert_all(entries):
    rows = []
    for entry in entries:
        try:
            rows.append(format_row(parse_temperature(entry)))
        except ValueError as error:
            rows.append('{0:<20} -> error: {1}'.format(entry.strip(), error))
    return rows


def main():
    samples = [
        '32',
        '212 F',
        '98.6',
        '  -40{0}F '.format(DEGREE_SIGN),
        '-500',
        'warm',
    ]
    print('Fahrenheit to Celsius conversion report')
    print('=' * 60)
    for row in convert_all(samples):
        print(row)
    freezing = fahrenheit_to_celsius(32)
    boiling = fahrenheit_to_celsius(212)
    print('-' * 60)
    print('checkpoints: {0:.1f} and {1:.1f}'.format(freezing, boiling))


if __name__ == '__main__':
    main()

