import sys


def _validate_list(name, value):
    if not isinstance(value, list):
        raise TypeError(name + ' must be a list')


def list_difference(list1, list2):
    _validate_list('list1', list1)
    _validate_list('list2', list2)
    seen = set()
    unhashable = []
    for item in list2:
        try:
            seen.add(item)
        except TypeError:
            unhashable.append(item)
    difference_list = []
    for item in list1:
        try:
            missing = item not in seen
        except TypeError:
            missing = True
        if missing and item not in unhashable:
            difference_list.append(item)
    return difference_list


def parse_tokens(text):
    stripped = text.strip()
    if stripped == '':
        return []
    tokens = []
    for raw in stripped.split(','):
        piece = raw.strip()
        try:
            tokens.append(int(piece))
        except ValueError:
            tokens.append(piece)
    return tokens


def format_items(items):
    if not items:
        return '(empty)'
    return ', '.join(repr(item) for item in items)


def format_report(list1, list2):
    difference_list = list_difference(list1, list2)
    removed = len(list1) - len(difference_list)
    lines = [
        'first list:  ' + format_items(list1),
        'second list: ' + format_items(list2),
        'difference:  ' + format_items(difference_list),
        'removed element(s): ' + str(removed),
    ]
    return '\n'.join(lines)


def usage(program):
    template = 'usage: {0} LIST1 LIST2 (comma-separated, e.g. 1,2,3,4)'
    return template.format(program)


def main(argv):
    if len(argv) != 3:
        sys.stderr.write(usage(argv[0]))
        sys.stderr.write('\n')
        return 2
    left = parse_tokens(argv[1])
    right = parse_tokens(argv[2])
    print(format_report(left, right))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

