import os
import sys

READ_MODE = 'r'
ENCODING = 'utf-8'
DECODE_ERRORS = 'replace'
ROW_FORMAT = '{:<30} {:>8} {:>10} {:>8} {:>10}'
COLUMNS = (
    'FILE',
    'LINES',
    'NONBLANK',
    'BLANK',
    'BYTES',
)


def count_file_lines(filepath):
    line_count = 0
    with open(filepath, READ_MODE, encoding=ENCODING, errors=DECODE_ERRORS) as handle:
        for _line in handle:
            line_count += 1
    return line_count


def count_nonblank_lines(filepath):
    nonblank = 0
    with open(filepath, READ_MODE, encoding=ENCODING, errors=DECODE_ERRORS) as handle:
        for line in handle:
            if line.strip():
                nonblank += 1
    return nonblank


def describe_file(filepath):
    if not os.path.isfile(filepath):
        raise FileNotFoundError('not a readable regular file: ' + filepath)
    total = count_file_lines(filepath)
    filled = count_nonblank_lines(filepath)
    return {
        'path': filepath,
        'lines': total,
        'nonblank': filled,
        'blank': total - filled,
        'bytes': os.path.getsize(filepath),
    }


def format_report(records):
    header = ROW_FORMAT.format(*COLUMNS)
    rows = [header, '-' * len(header)]
    for record in records:
        rows.append(
            ROW_FORMAT.format(
                os.path.basename(record['path']),
                record['lines'],
                record['nonblank'],
                record['blank'],
                record['bytes'],
            )
        )
    if len(records) > 1:
        grand = sum(record['lines'] for record in records)
        summary = 'total lines across {} files: {}'
        rows.append(summary.format(len(records), grand))
    return '\n'.join(rows)


def main(argv):
    if len(argv) < 2:
        sys.stderr.write('usage: linecount.py FILE [FILE ...]\n')
        return 2
    records = []
    for filepath in argv[1:]:
        try:
            records.append(describe_file(filepath))
        except OSError as exc:
            sys.stderr.write('skipping {}: {}\n'.format(filepath, exc))
    if not records:
        sys.stderr.write('no files could be read\n')
        return 1
    print(format_report(records))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

