def update_dict(dict1, dict2):
    if not isinstance(dict1, dict):
        raise TypeError('dict1 must be a dict')
    if not isinstance(dict2, dict):
        raise TypeError('dict2 must be a dict')
    merged_dict = dict(dict1)
    merged_dict.update(dict2)
    return merged_dict


LABELS = (
    'added',
    'updated',
    'unchanged',
)


def classify_keys(dict1, dict2):
    changes = {label: [] for label in LABELS}
    for key in dict2:
        if key not in dict1:
            changes['added'].append(key)
        elif dict1[key] != dict2[key]:
            changes['updated'].append(key)
        else:
            changes['unchanged'].append(key)
    for key in dict1:
        if key not in dict2:
            changes['unchanged'].append(key)
    return changes


def format_pair(key, value):
    return '{0!r}: {1!r}'.format(key, value)


def format_dict(mapping):
    body = ', '.join(format_pair(key, value) for key, value in mapping.items())
    return '{{{0}}}'.format(body)


def format_keys(keys):
    if not keys:
        return 'none'
    ordered = sorted(keys, key=repr)
    return ', '.join(repr(key) for key in ordered)


def describe_merge(dict1, dict2):
    merged_dict = update_dict(dict1, dict2)
    changes = classify_keys(dict1, dict2)
    lines = ['result: ' + format_dict(merged_dict)]
    for label in LABELS:
        lines.append('{0}: {1}'.format(label, format_keys(changes[label])))
    return '\n'.join(lines)


