import sys


def cubes_up_to(limit):
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise TypeError('limit must be an integer')
    if limit < 0:
        raise ValueError('limit must be non-negative')
    cubes_list = [n ** 3 for n in range(limit + 1)]
    return cubes_list


def parse_limit(text):
    stripped = text.strip()
    if not stripped:
        raise ValueError('limit must not be empty')
    if stripped.startswith('+'):
        stripped = stripped[1:]
    if not stripped.isdigit():
        raise ValueError('not a non-negative integer: ' + repr(text))
    return int(stripped)


def format_table(cubes_list):
    width = max(len(str(value)) for value in cubes_list)
    separator = ' | '
    header_cells = [
        'n'.rjust(3),
        'n^3'.rjust(width),
    ]
    rule_cells = ['-' * len(cell) for cell in header_cells]
    lines = [separator.join(header_cells)]
    lines.append('-+-'.join(rule_cells))
    for n, value in enumerate(cubes_list):
        row_cells = [str(n).rjust(3), str(value).rjust(width)]
        lines.append(separator.join(row_cells))
    return '\n'.join(lines)


def summarize(cubes_list):
    parts = [
        'count={0}'.format(len(cubes_list)),
        'sum={0}'.format(sum(cubes_list)),
        'max={0}'.format(cubes_list[-1]),
    ]
    return ', '.join(parts)


def run(argv):
    if len(argv) > 1:
        sources = argv[1:]
    else:
        sources = '3 0 6'.split()
    exit_code = 0
    for source in sources:
        try:
            limit = parse_limit(source)
            cubes_list = cubes_up_to(limit)
        except (TypeError, ValueError) as error:
            print('error: ' + str(error), file=sys.stderr)
            exit_code = 1
            continue
        print('cubes up to {0}:'.format(limit))
        print(format_table(cubes_list))
        print(summarize(cubes_list))
        print('')
    return exit_code


if __name__ == '__main__':
    sys.exit(run(sys.argv))

