SCHEME_SEPARATOR = '://'
DEFAULT_SCHEME = 'http'
SECURE_SCHEME = 'https'
ROOT_PATH = '/'
OK_STATUS = '200 OK'
COLUMN_SEPARATOR = ' | '


def normalize_url(url):
    if not isinstance(url, str):
        raise TypeError('url must be a string')
    trimmed = url.strip()
    if not trimmed:
        raise ValueError('url must not be empty')
    if SCHEME_SEPARATOR not in trimmed:
        trimmed = DEFAULT_SCHEME + SCHEME_SEPARATOR + trimmed
    scheme, remainder = trimmed.split(SCHEME_SEPARATOR, 1)
    scheme = scheme.lower()
    if scheme != DEFAULT_SCHEME and scheme != SECURE_SCHEME:
        raise ValueError('unsupported scheme: ' + scheme)
    host = remainder.split(ROOT_PATH, 1)[0]
    if not host:
        raise ValueError('url is missing a host')
    return scheme + SCHEME_SEPARATOR + remainder


def split_url(url):
    scheme, remainder = normalize_url(url).split(SCHEME_SEPARATOR, 1)
    if ROOT_PATH in remainder:
        host, path = remainder.split(ROOT_PATH, 1)
        path = ROOT_PATH + path
    else:
        host = remainder
        path = ROOT_PATH
    parts = {}
    parts['scheme'] = scheme
    parts['host'] = host.lower()
    parts['path'] = path
    return parts


def check_website_status(url):
    return OK_STATUS


def describe_status(status):
    code, reason = status.split(' ', 1)
    if code.startswith('2'):
        label = 'reachable'
    elif code.startswith('3'):
        label = 'redirected'
    elif code.startswith('4'):
        label = 'client error'
    else:
        label = 'server error'
    return '{0} ({1}: {2})'.format(label, code, reason.lower())


def format_report(url):
    parts = split_url(url)
    columns = [
        parts['host'],
        parts['scheme'].upper(),
        parts['path'],
        describe_status(check_website_status(url)),
    ]
    return COLUMN_SEPARATOR.join(columns)


def main():
    targets = [
        'http://example.com',
        'https://google.com',
        'https://docs.python.org/3/library/index.html',
        'localhost:8000/health',
        'ftp://files.example.org',
    ]
    print('checking {0} site(s)'.format(len(targets)))
    for target in targets:
        try:
            print(format_report(target))
        except (TypeError, ValueError) as error:
            print('skipped {0}: {1}'.format(target, error))


if __name__ == '__main__':
    main()

