def calculate_range(numbers):
    if not numbers:
        raise ValueError('Input list cannot be empty.')

    if len(numbers) == 1:
        return 0

    max_val = numbers[0]
    min_val = numbers[0]

    for num in numbers:
        if num > max_val:
            max_val = num
        if num < min_val:
            min_val = num

    result_range = max_val - min_val
    return result_range

def test_calculate_range():
