import random

DIE_FACES = 6


def validate_num_dice(num_dice):
    if isinstance(num_dice, bool) or not isinstance(num_dice, int):
        raise TypeError('num_dice must be an integer')
    if num_dice < 1:
        raise ValueError('num_dice must be at least 1')
    return num_dice


def roll_dice(num_dice):
    validate_num_dice(num_dice)
    return [random.randint(1, DIE_FACES) for _ in range(num_dice)]


def simulate_dice_sum(num_dice):
    total_sum = sum(roll_dice(num_dice))
    return total_sum


def format_roll(rolls):
    faces = ' + '.join(str(face) for face in rolls)
    return '{0} = {1}'.format(faces, sum(rolls))


def label_dice(num_dice):
    if num_dice == 1:
        return 'die'
    return 'dice'


def distribution(num_dice, trials):
    validate_num_dice(num_dice)
    if trials < 1:
        raise ValueError('trials must be at least 1')
    counts = {}
    for _ in range(trials):
        total = simulate_dice_sum(num_dice)
        counts[total] = counts.get(total, 0) + 1
    return counts


def histogram(counts, width=40):
    if not counts:
        return 'no data'
    peak = max(counts.values())
    lines = []
    for total in sorted(counts):
        bar = '#' * max(1, counts[total] * width // peak)
        lines.append('{0:>3} | {1} {2}'.format(total, bar, counts[total]))
    return '\n'.join(lines)


def main():
    for num_dice in (1, 2, 3):
        rolls = roll_dice(num_dice)
        label = label_dice(num_dice)
        print('{0} {1}: {2}'.format(num_dice, label, format_roll(rolls)))
    trials = 6000
    print('distribution of two dice over {0} trials'.format(trials))
    counts = distribution(2, trials)
    print(histogram(counts))
    average = sum(total * n for total, n in counts.items()) / trials
    print('observed mean: {0:.3f}'.format(average))
    print('expected mean: 7.000')
    try:
        simulate_dice_sum(0)
    except ValueError as error:
        print('rejected 0 dice: {0}'.format(error))


if __name__ == '__main__':
