def parse_csv_line(csv_line: str) -> list[str]:
    'Parses a single line of CSV data into a list of strings.'
    if not isinstance(csv_line, str):
        raise TypeError('Input must be a string.')
    if not csv_line:
        return []

    result = []
    current_field = ''
    for char in csv_line:
        if char == ',':
            result.append(current_field.strip())
            current_field = ''
        else:
            current_field += char
    result.append(current_field.strip())

    if not result:
        print('Warning: No fields parsed.')

    return result

