def longest_common_prefix(strings: list[str]) -> str:
    if not strings:
        return ''

    shortest_string = min(strings, key=len)
    common_prefix = ''

    for i, char in enumerate(shortest_string):
        is_common = True
        for s in strings:
            if s[i] != char:
                is_common = False
                break
        if is_common:
            common_prefix += char
        else:
            break

    return common_prefix

