def is_valid_octet(octet):
    if not octet or len(octet) > 3:
        return False
    if not octet.isdigit():
        return False
    if len(octet) > 1 and octet.startswith('0'):
        return False
    return 0 <= int(octet) <= 255


def is_valid_ipv4(ip_address):
    if not isinstance(ip_address, str):
        return False
    parts = ip_address.split('.')
    if len(parts) != 4:
        return False
    return all(is_valid_octet(part) for part in parts)


def classify_ipv4(ip_address):
    if not is_valid_ipv4(ip_address):
        return 'invalid'
    octets = [int(part) for part in ip_address.split('.')]
    if octets[0] == 127:
        return 'loopback'
    if octets[0] == 10:
        return 'private'
    if octets[0] == 172 and 16 <= octets[1] <= 31:
        return 'private'
    if octets[0] == 192 and octets[1] == 168:
        return 'private'
    if octets[0] == 169 and octets[1] == 254:
        return 'link-local'
    if 224 <= octets[0] <= 239:
        return 'multicast'
    return 'public'


def describe(ip_address):
    kind = classify_ipv4(ip_address)
    if kind == 'invalid':
        return '{0!r} is not a valid IPv4 address'.format(ip_address)
    return '{0} is a valid {1} address'.format(ip_address, kind)


def summarize(addresses):
    counts = {}
    for address in addresses:
        kind = classify_ipv4(address)
        counts[kind] = counts.get(kind, 0) + 1
    return counts


def main():
    samples = [
        '192.168.1.1',
        '256.0.0.1',
