        '1.2.3',
        '01.2.3.4',
        ' 10.0.0.1',
        '1.2.3.4.5',
    ]
    for sample in samples:
        print(describe(sample))
    totals = summarize(samples)
    print('--- summary ---')
    for kind in sorted(totals):
        print('{0:>12}: {1}'.format(kind, totals[kind]))


if __name__ == '__main__':
