def is_perfect_number(number: int) -> bool:
    if number <= 0:
        raise ValueError('Input must be a positive integer.')
    if number == 1:
        return False

    divisors_sum = 1
    for i in range(2, int(number**0.5) + 1):
        if number % i == 0:
            divisors_sum += i
            if i * i != number:
                divisors_sum += number // i

    return divisors_sum == number

