def generate_primes(n):
    if n < 2:
        return []

    primes = []
    candidates = list(range(2, n + 1)) # 'range' is efficient

    for num in candidates:
        is_prime = True # 'boolean flag'
        if num == 2:
            primes.append(num)
            continue # 'skip'
        if num % 2 == 0:
            is_prime = False # 'even numbers'

        for i in range(3, int(num**0.5) + 1, 2): # 'optimization'
            if num % i == 0:
                is_prime = False
                break # 'not prime'

        if is_prime:
            primes.append(num) # 'found a prime'

    return primes # 'result'

