import collections
import os
import sys

READ_MODE = 'r'
ENCODING = 'utf-8'
PUNCTUATION = '.,;:!?"\''
NO_WORDS = '(none)'
DEFAULT_PATH = 'test.txt'
LIST_SEPARATOR = ', '
FIELDS = 'name words lines longest'

FileReport = collections.namedtuple('FileReport', FIELDS)


def count_words_in_file(filepath):
    total = 0
    with open(filepath, READ_MODE, encoding=ENCODING) as handle:
        for line in handle:
            total += len(line.split())
    return total


def count_lines_in_file(filepath):
    with open(filepath, READ_MODE, encoding=ENCODING) as handle:
        return sum(1 for _line in handle)


def longest_word_in_file(filepath):
    longest = NO_WORDS
    best = 0
    with open(filepath, READ_MODE, encoding=ENCODING) as handle:
        for line in handle:
            for word in line.split():
                stripped = word.strip(PUNCTUATION)
                if len(stripped) > best:
                    longest = stripped
                    best = len(stripped)
    return longest


def build_report(filepath):
    return FileReport(
        os.path.basename(filepath),
        count_words_in_file(filepath),
        count_lines_in_file(filepath),
        longest_word_in_file(filepath),
    )


def format_report(report):
    rows = [
        f'file: {report.name}',
        f'words: {report.words}',
        f'lines: {report.lines}',
        f'longest word: {report.longest}',
    ]
    return '\n'.join(rows)


def main(argv):
    paths = argv[1:] or [DEFAULT_PATH]
    missing = [path for path in paths if not os.path.isfile(path)]
    if missing:
        print(f'error: cannot read {LIST_SEPARATOR.join(missing)}')
        return 1
    for path in paths:
        print(format_report(build_report(path)))
        print('-' * 24)
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

