def convert_length(value, from_unit, to_unit):
    'Converts length between meters and feet.'
    meter_to_feet_factor = 3.28084

    if from_unit == 'm' and to_unit == 'ft':
        result = value * meter_to_feet_factor
    elif from_unit == 'ft' and to_unit == 'm':
        result = value / meter_to_feet_factor
    elif from_unit == to_unit:
        'Units are the same, no conversion needed.'
        result = value
    else:
        'Error: Invalid unit combination.'
        raise ValueError('Invalid unit conversion specified.')

    return float(result)

