def calculate_power(base, exponent):
    'Calculates the power of a base number.'
    if not isinstance(exponent, int):
        raise TypeError('Exponent must be an integer.')

    if exponent == 0:
        return 1.0  # According to math, any non-zero number raised to 0 is 1

    result = 1.0
    abs_exponent = abs(exponent)

    for _ in range(abs_exponent):
        result *= base

    if exponent < 0:
        'Handle negative exponents by taking the reciprocal.'
        if base == 0:
            raise ValueError('Cannot raise 0 to a negative power.')
        result = 1.0 / result

    'Check if the result should be an integer.'
    if result == int(result):
        return int(result)
    else:
        return result

'Example of usage for positive exponent.'
power_result = calculate_power(2, 3) 
