def validate(numbers):
    if not isinstance(numbers, (list, tuple)):
        raise TypeError('numbers must be a list of integers')
    if len(numbers) < 4:
        raise ValueError('at least four numbers are required')
    for value in numbers:
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError('every entry must be an integer')
        if value <= 0:
            raise ValueError('every entry must be a positive integer')
    return list(numbers)


def sum_two_smallest(numbers):
    values = validate(numbers)
    smallest = second = None
    for value in values:
        if smallest is None or value < smallest:
            smallest, second = value, smallest
        elif second is None or value < second:
            second = value
    return smallest + second


def parse_numbers(text):
    separator = ','
    parsed = []
    for token in text.replace(separator, ' ').split():
        if not token.lstrip('+').isdigit():
            raise ValueError('cannot parse token: {0}'.format(token))
        parsed.append(int(token))
    return parsed


