class BankAccount:
    '''A simple bank account with deposits, withdrawals and a transaction log.'''

    def __init__(self, initial_balance=0):
        if not isinstance(initial_balance, (int, float)) or isinstance(initial_balance, bool):
            raise TypeError('initial_balance must be a number')
        if initial_balance < 0:
            raise ValueError('initial_balance must not be negative')
        self.balance = initial_balance
        self.history = [('open', initial_balance)]

    def _valid(self, amount):
        if not isinstance(amount, (int, float)) or isinstance(amount, bool):
            return False
        return amount > 0

    def deposit(self, amount):
        if not self._valid(amount):
            return False
        self.balance += amount
        self.history.append(('deposit', amount))
        return True

    def withdraw(self, amount):
        if not self._valid(amount) or amount > self.balance:
            return False
        self.balance -= amount
        self.history.append(('withdraw', amount))
        return True

    def statement(self):
        lines = []
        running = 0
        for kind, amount in self.history:
            if kind == 'withdraw':
                running -= amount
                sign = '-'
            else:
                running += amount
                sign = '+'
            lines.append('{:<9} {}{:>8.2f} {:>10.2f}'.format(kind, sign, amount, running))
        return '\n'.join(lines)

    def __repr__(self):
        return 'BankAccount(balance={:.2f})'.format(self.balance)


def run_operations(account, operations):
    '''Apply (action, amount) pairs and report the outcome of each one.'''
    report = []
    for action, amount in operations:
        if action == 'deposit':
            ok = account.deposit(amount)
        elif action == 'withdraw':
            ok = account.withdraw(amount)
        else:
            raise ValueError('unknown action: ' + repr(action))
        outcome = 'ok'
        if not ok:
            outcome = 'rejected'
        report.append('{} {:.2f} -> {} (balance {:.2f})'.format(action, amount, outcome, account.balance))
    return report


def main():
    acc = BankAccount(100)
    plan = [
        ('deposit', 50),
        ('withdraw', 200),
        ('withdraw', 75.5),
        ('deposit', -10),
    ]
    for line in run_operations(acc, plan):
        print(line)
    print('--- statement ---')
    print(acc.statement())
    print('final:', acc)


if __name__ == '__main__':
    main()

