def _parse_vector(text):
    cleaned = text.strip().strip('()[]')
    parts = [piece.strip() for piece in cleaned.split(',')]
    if len(parts) != 2:
        raise ValueError('a 2D vector needs exactly two components')
    numbers = []
    for part in parts:
        try:
            numbers.append(int(part))
        except ValueError:
            numbers.append(float(part))
    return tuple(numbers)


def _parse_pair(line):
    halves = line.split(';')
    if len(halves) != 2:
        raise ValueError('a pair needs two vectors separated by a semicolon')
    return _parse_vector(halves[0]), _parse_vector(halves[1])


def _validate_vector(vec, name):
    if len(vec) != 2:
        raise ValueError(name + ' must have exactly two components')
    for component in vec:
        if isinstance(component, bool) or not isinstance(component, (int, float)):
            raise TypeError(name + ' must contain only numbers')


def calculate_dot_product(vec1, vec2):
    _validate_vector(vec1, 'vec1')
    _validate_vector(vec2, 'vec2')
    return vec1[0] * vec2[0] + vec1[1] * vec2[1]


def classify_angle(vec1, vec2):
    product = calculate_dot_product(vec1, vec2)
    if product > 0:
        return 'acute'
    if product < 0:
        return 'obtuse'
    return 'perpendicular'


def _format_number(value):
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def format_vector(vec):
    joined = ', '.join(_format_number(component) for component in vec)
    return '({})'.format(joined)


def describe_pair(vec1, vec2):
    product = calculate_dot_product(vec1, vec2)
    template = '{} . {} = {} ({})'
    return template.format(
        format_vector(vec1),
        format_vector(vec2),
        _format_number(product),
        classify_angle(vec1, vec2),
    )


def main():
    lines = [
        '(1, 2); (3, 4)',
        '(0, 5); (10, 0)',
        '-1.5, 2; 4, 0.5',
        '[2, 2]; [-3, 1]',
    ]
    for line in lines:
        try:
            vec1, vec2 = _parse_pair(line)
        except ValueError as error:
            print('skipping pair:', error)
            continue
        print(describe_pair(vec1, vec2))


if __name__ == '__main__':
    main()

